mapper.select:
select po.user_id,po.plus_orderid,po.pay_price,po.pay_type,po.start_time,po.end_time, po.thali_type,po.creat_time,ui.user_name,ui.user_mobile,pr.renew_status from ${database.prefix.userms}hou_user_plus_order po left join ${database.prefix.userms}hou_user_info ui on po.user_id = ui.user_id left join ${database.prefix.userms}hou_user_plus_renew pr on po.plus_orderid = pr.plus_orderid where 1 = 1 and po.is_pay = 1
and po.user_id = #{param.userId}
order by po.creat_time desc

SELECT
po.user_id,
po.plus_orderid,
po.pay_price,
po.pay_type,
po.start_time,
po.end_time,
po.thali_type,
po.creat_time,
ui.user_name,
ui.user_mobile
FROM
${database.prefix.userms}hou_user_plus_order po
LEFT JOIN ${database.prefix.userms}hou_user_info ui ON po.user_id = ui.user_id
WHERE 1 = 1

    and po.user_id = #{param.userId}


    and ui.user_name = #{param.userName}


    and ui.user_mobile = #{param.userMobile}


    and po.pay_type = #{param.payType}


    and po.thali_type = #{param.thaliType}


    and po.start_time between #{param.startTime} and #{param.endTime}


    and po.end_time between #{param.startTime} and #{param.endTime}


    and po.plus_orderid in

        #{id}



order by po.creat_time desc

SELECT
po.user_id as userId,
po.plus_orderid as plusOrderid,
po.pay_price as payPrice,
po.pay_type as payType,
date_format(po.start_time, '%Y-%m-%d %H:%i:%s' )  as startTime,
date_format(po.end_time, '%Y-%m-%d %H:%i:%s' ) as endTime,
po.thali_type as thaliType,
date_format(po.creat_time, '%Y-%m-%d %H:%i:%s' ) as creatTime,
ifnull(ui.user_name,null) as userName,
ifnull(ui.user_mobile,null) as userMobile
FROM
${database.prefix.userms}hou_user_plus_order po
LEFT JOIN ${database.prefix.userms}hou_user_info ui ON po.user_id = ui.user_id
WHERE 1 = 1 and po.is_pay  = 1

    and po.user_id = #{param.userId}


    and ui.user_name = #{param.userName}


    and ui.user_mobile = #{param.userMobile}


    and po.pay_type = #{param.payType}


    and po.thali_type = #{param.thaliType}


    and po.start_time between #{param.startTime} and #{param.endTime}


    and po.end_time between #{param.startTime} and #{param.endTime}

order by po.creat_time desc
